use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

    /// Given a non-empty Vec<i8>, produce a new Vec<i8> of the same length
    /// where each element is:
    ///   - -1 if the input element is negative,
    ///   -  0 if the input element is zero,
    ///   -  1 if the input element is positive.
    pub fn sign(x: Vec<i8>) -> (result: Vec<i8>)
        ensures result.len() == x.len()
        ensures forall |i: usize| i < x.len() ==>
            if x.index(i) < 0 {
                result.index(i) == -1
            } else if x.index(i) == 0 {
                result.index(i) == 0
            } else {
                result.index(i) == 1
            }
    {
        let n = x.len();
        // We build `result` incrementally.
        let mut result = Vec::new();
        result.reserve(n);

        let mut i: usize = 0;
        while i < n {
            // Invariant: we've processed exactly `i` elements,
            // and each result[j] for j<i matches the sign spec.
            invariant i <= n;
            invariant result.len() == i;
            invariant forall |j: usize| j < i ==>
                if x.index(j) < 0 {
                    result.index(j) == -1
                } else if x.index(j) == 0 {
                    result.index(j) == 0
                } else {
                    result.index(j) == 1
                };
            decreases n - i;

            // Extract the ith element from `x`.
            let xi: i8 = *x.get(i).unwrap();
            // Classify its sign.
            let si: i8 =
                if xi < 0 {
                    -1
                } else if xi == 0 {
                    0
                } else {
                    1
                };
            // Append to result.
            result.push(si);

            i += 1;
        }

        // At this point, i == n and result.len() == n,
        // and by the loop invariant we have established the postcondition.
        result
    }

}